using System.IO;
using FizzWare.NBuilder;
using NUnit.Framework;
using NzbDrone.Core.Datastore.Migration.Framework;
using NzbDrone.Core.Tv;
using NzbDrone.Test.Common.Datastore;

namespace NzbDrone.Core.Test
{
    [SetUpFixture]
    public class RemoveCachedDatabase
    {
        [OneTimeSetUp]
        public void ConfigureOptionalSeriesGroupingProperties()
        {
            // Generic series fixtures describe unrelated entries. Autogenerated group
            // strings would instead claim the same unique group/season slot each time a
            // fixture creates a separate builder. Grouping tests set membership explicitly.
            BuilderSetup.DisablePropertyNamingFor<Series, AnimeGroupingMode>(s => s.AnimeGroupingMode);
            BuilderSetup.DisablePropertyNamingFor<Series, string>(s => s.AnimeGroupId);
            BuilderSetup.DisablePropertyNamingFor<Series, string>(s => s.AnimeGroupTitle);
            BuilderSetup.DisablePropertyNamingFor<Series, int?>(s => s.AnimeGroupSeasonNumber);
            BuilderSetup.DisablePropertyNamingFor<Series, string>(s => s.AnimeGroupFolder);
            BuilderSetup.DisablePropertyNamingFor<Series, AnimeGroupMemberKind>(s => s.AnimeGroupMemberKind);
            BuilderSetup.DisablePropertyNamingFor<Series, AnimeGroupKind>(s => s.AnimeGroupKind);
            BuilderSetup.DisablePropertyNamingFor<Series, AnimeGroupMovieFolderStyle>(s => s.AnimeGroupMovieFolderStyle);
            BuilderSetup.DisablePropertyNamingFor<Series, int?>(s => s.AnimeGroupMovieNumber);
            BuilderSetup.DisablePropertyNamingFor<Series, string>(s => s.AnimeGroupMemberFolder);
        }

        [OneTimeSetUp]
        [OneTimeTearDown]
        public void ClearCachedDatabase()
        {
            var mainCache = SqliteDatabase.GetCachedDb(MigrationType.Main);
            if (File.Exists(mainCache))
            {
                File.Delete(mainCache);
            }

            var logCache = SqliteDatabase.GetCachedDb(MigrationType.Log);
            if (File.Exists(logCache))
            {
                File.Delete(logCache);
            }
        }
    }
}
